import { registerWebComponents } from '@domg-wc/common';
import { VlStepsComponent } from '@domg-wc/components/block';

// vl-steps registreert zelf vl-step en vl-duration-step; @domg-wc/components/block exporteert enkel VlStepsComponent.
registerWebComponents([VlStepsComponent]);

// vl-on-toggle borrelt niet op: luister op elke vl-step. event.detail.open zegt of de stap nu open is.
document.querySelectorAll('vl-step[toggleable]').forEach((step) => {
    step.addEventListener('vl-on-toggle', (event) => console.log('vl-on-toggle', event.detail));
});

import { registerWebComponents } from '@domg-wc/common';
import { VlStepsComponent } from '@domg-wc/components/block';
import { html } from 'lit';

registerWebComponents([VlStepsComponent]);

// contentRenderer krijgt de open/closed state en geeft een lit TemplateResult terug; het content slot wordt dan
// genegeerd. De ids staan niet in de story, die de property rechtstreeks in de template zet.
document.querySelector('#step-dynamische-content').contentRenderer = (open) =>
    open
        ? html`<p><strong>Open:</strong> Dit is de uitgebreide content die alleen zichtbaar is wanneer de step geopend is.</p>`
        : html`<p><em>Gesloten:</em> Klik om meer te zien...</p>`;

document.querySelector('#step-complexe-content').contentRenderer = (open) =>
    open
        ? html`
              <div>
                  <p>De step is nu open!</p>
                  <ul>
                      <li>Item 1</li>
                      <li>Item 2</li>
                      <li>Item 3</li>
                  </ul>
              </div>
          `
        : html`<p>Samenvatting...</p>`;
